// Emit the TS voice-framing and vocoder tables as a C++ header, so the C++ port
// uses exactly the same numbers (no hand transcription).
//
//   node --experimental-strip-types gen_tables.ts > cpp/tables.gen.hpp

import * as voice from "../../archive/ts-engine/src/vendor/ff/p25/voiceTables.ts";
import * as mbe from "../../archive/ts-engine/src/vendor/ff/mbe/tables.ts";

const out: string[] = [
  "// GENERATED by research/native-bench/gen_tables.ts from src/vendor/ff/p25/voiceTables.ts",
  "// (op25_imbe_frame.h, GPLv3) and src/vendor/ff/mbe/tables.ts (mbelib, ISC). Do not edit.",
  "#pragma once",
  "#include <cstdint>",
  "namespace tables {",
];

function emit(name: string, a: ArrayLike<number>) {
  const float = a instanceof Float32Array || a instanceof Float64Array;
  const type = float ? "float" : a instanceof Int16Array ? "int16_t" : a instanceof Uint16Array ? "uint16_t" : "int32_t";
  const vals = Array.from(a, (v) => (float ? (Number.isInteger(v) ? `${v}.0f` : `${Math.fround(v)}f`) : String(v)));
  const lines: string[] = [];
  for (let i = 0; i < vals.length; i += 16) lines.push("  " + vals.slice(i, i + 16).join(", ") + ",");
  out.push(`inline constexpr ${type} ${name}[${vals.length}] = {`, ...lines, "};");
}

for (const [mod, ns] of [
  [voice, "voice"],
  [mbe, "mbe"],
] as const) {
  for (const [k, v] of Object.entries(mod)) {
    if (ArrayBuffer.isView(v)) emit(k, v as unknown as ArrayLike<number>);
    else console.error(`skipped ${ns}.${k} (${typeof v})`);
  }
}
out.push("}  // namespace tables", "");
console.log(out.join("\n"));
